// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address potentialOwner) public {
        vm.assume(potentialOwner != address(0));

        vm.prank(potentialOwner);
        c.initialize();

        address reportedOwner = c.owner();

        assertTrue(reportedOwner == potentialOwner);
    }
}
